"use client";

/**
 * Burn Away
 *
 * Two real HTML pages, an editorial article and a product landing page, drawn into WebGL with Chrome's
 * HTML-in-Canvas API. A click sets the top page alight: the paper toasts, chars and burns open in a ragged
 * glowing ring, with flames, embers, flakes and smoke, and the page underneath is already there, live.
 * The landing page is a working page: its counters tick, its email field takes real typing, and its button
 * burns it back to the article.
 *
 * Usage
 *   <section style={{ position: "relative", height: "80vh" }}>
 *     <BurnAway productName="Afterglow" headline="Leave a mark on" headlineAccent="every click." />
 *   </section>
 *
 * Fills its positioned parent and scales the two 1040×580 pages to fit. Idle, it plays the burn on its own
 * (click, burn, type, click, burn back) and loops; a visitor's click or key takes over, and the loop comes
 * back after 6 s idle. It pauses off screen and in hidden tabs; prefers-reduced-motion gets a still frame
 * and instant page swaps.
 *
 * Browser support
 *   The WebGL burn needs Chrome 157+ (HTML-in-Canvas: <canvas layoutsubtree> + texElementSubImage2D).
 *   Safari, Firefox and older Chrome get the same two pages as plain HTML with a crossfade and a small note.
 *
 * Theming
 *   The stage, its vignette and shadow, the fire glow on the stage, the badge and the fallback chrome follow
 *   your shadcn theme: light by default (a soft stone stage with real paper shadows), dark under a `.dark`
 *   ancestor (a warm near-black stage). It reads the Tailwind v4 variables --color-background, --color-muted,
 *   --color-card, --color-border, --color-foreground and --color-muted-foreground, with fallbacks, and re-reads
 *   them when the theme changes. The two pages keep their own designs in both themes. Pass theme="light" or
 *   theme="dark" to fix it.
 *
 * No dependencies besides React.
 */

import * as React from "react";

export interface BurnAwayProps {
  /** Playback speed of the burn and the idle loop (0.5 to 2). */
  speed?: number;
  /** Brightness of the fire: rim glow, flames, embers (0.3 to 1.6). */
  intensity?: number;
  /** Play the click-burn-type-burn loop on its own while nobody is interacting. */
  autoplay?: boolean;
  /** The small "Two real HTML pages" pill under the pages. */
  badge?: boolean;
  /** "auto" follows the `.dark` class like shadcn; "light" or "dark" fixes the stage. */
  theme?: "auto" | "light" | "dark";
  /** Brand on the landing page. */
  productName?: string;
  /** Magazine on the article page, set after "The". */
  magazine?: string;
  /** Small red line above the article headline. */
  kicker?: React.ReactNode;
  /** Article headline. Wrap a word in <em> to set it in red. */
  articleTitle?: React.ReactNode;
  /** Article standfirst under the headline. */
  articleStandfirst?: React.ReactNode;
  /** Byline row under the standfirst. */
  byline?: React.ReactNode;
  /** Article body; its first letter becomes the drop cap. */
  articleBody?: string;
  /** Pull quote beside the article. */
  pullQuote?: React.ReactNode;
  /** Landing-page headline, then its highlighted second half. */
  headline?: React.ReactNode;
  /** Highlighted (lime) second half of the landing-page headline. */
  headlineAccent?: React.ReactNode;
  /** Landing-page line under the headline. Defaults to a line about `productName`. */
  tagline?: React.ReactNode;
  /** Placeholder of the email field. */
  emailPlaceholder?: string;
  /** What the idle loop types into the email field. */
  email?: string;
  /** Label of the landing-page button. */
  ctaLabel?: string;
  /** Label the button shows once pressed. */
  ctaDoneLabel?: string;
  /** Small print under the email field. */
  finePrint?: React.ReactNode;
  /** Extra class on the root. */
  className?: string;
  /** Extra style on the root (it is absolutely positioned to fill its parent). */
  style?: React.CSSProperties;
}

const PW = 1040
const PH = 580
const NBARS = 22

// Stage palettes as CSS custom properties (--ba-*). Values that read a shadcn token keep a fallback, so the
// stage also works without a theme. A fixed theme ("light" / "dark") uses only the fallbacks.
// bg0 / bg1: stage centre / edge (the WebGL stage reads them as uniforms). sh: page shadow strength. light: 1 / 0.
const LIGHT: Record<string, string> = {
  bg0: "color-mix(in oklab, var(--color-muted, #f4f4f5) 50%, #ece9e3)",
  bg1: "color-mix(in oklab, var(--color-muted, #f4f4f5) 25%, #d2ccc2)",
  sh: ".27",
  light: "1",
  pshadow: "0 1px 2px #3b2a1a24,0 26px 60px -14px #3b2a1a59,0 0 0 1px #3b2a1a1a",
  rip: "0 0 0 3px #fff,0 0 0 4.5px #1c181338,0 0 24px #ff7a2e",
  tagbg: "color-mix(in oklab, var(--color-card, #ffffff) 78%, transparent)",
  tagline: "color-mix(in oklab, var(--color-border, #e4e4e7) 90%, #5b4630)",
  tagsh: "0 6px 18px -8px #3b2a1a40",
  tagfg: "var(--color-muted-foreground, #6f6458)",
  tagb: "var(--color-foreground, #1c1813)",
  dot: "#f0621f",
};
const DARK: Record<string, string> = {
  bg0: "color-mix(in oklab, var(--color-background, #0a0a0a) 40%, #2a1912)",
  bg1: "color-mix(in oklab, var(--color-background, #0a0a0a) 35%, #030202)",
  sh: ".72",
  light: "0",
  pshadow: "0 30px 70px #000a,0 0 0 1px #ffffff10",
  rip: "0 0 0 3px #fff,0 0 24px #ffb45a",
  tagbg: "#ffffff12",
  tagline: "#ffffff26",
  tagsh: "0 0 0 0 transparent",
  tagfg: "color-mix(in oklab, var(--color-muted-foreground, #a1a1aa) 50%, #efe6dc)",
  tagb: "#ffffff",
  dot: "#ff8a3d",
};
const decl = (p: Record<string, string>, fixed: boolean) =>
  Object.keys(p)
    .map((k) => `--ba-${k}:${fixed ? p[k].replace(/var\(--[a-z-]+, (#[0-9A-Fa-f]+)\)/g, "$1") : p[k]}`)
    .join(";");
function themeCss() {
  return `.ba-root{${decl(LIGHT, false)}}
:where(.dark) .ba-root,.ba-root:where(.dark){${decl(DARK, false)}}
.ba-root[data-ba-theme="light"]{${decl(LIGHT, true)}}
.ba-root[data-ba-theme="dark"]{${decl(DARK, true)}}`;
}

