/* ---- noise shared by GLSL and JS (same integer hash, so embers are born exactly on the burning rim) ---- */
const NOISE = `
float ss(float a, float b, float x){ float t = clamp((x-a)/(b-a), 0., 1.); return t*t*(3.-2.*t); }
float hash(ivec2 i){ uvec2 v = uvec2(i)*1664525u + 1013904223u; v.x += v.y*1664525u; v.y += v.x*1664525u; v ^= v>>16u;
  v.x += v.y*1664525u; v.y += v.x*1664525u; v ^= v>>16u; return float(v.x)/4294967295.; }
float vnoise(vec2 p){ vec2 i = floor(p), f = fract(p); vec2 u = f*f*(3.-2.*f); ivec2 k = ivec2(i);
  return mix(mix(hash(k), hash(k+ivec2(1,0)), u.x), mix(hash(k+ivec2(0,1)), hash(k+ivec2(1,1)), u.x), u.y); }
float fbm(vec2 p){ float s = 0., a = .5, t = 0.; for (int i = 0; i < 5; i++){ s += a*vnoise(p); t += a; p = mat2(.8,.6,-.6,.8)*p*2.02 + 17.3; a *= .5; } return s/t; }
`
const HM = 1664525
const HA = 1013904223
function hash(x: number, y: number) {
  let vx = (Math.imul(x, HM) + HA) >>> 0
  let vy = (Math.imul(y, HM) + HA) >>> 0
  vx = (vx + Math.imul(vy, HM)) >>> 0
  vy = (vy + Math.imul(vx, HM)) >>> 0
  vx = (vx ^ (vx >>> 16)) >>> 0
  vy = (vy ^ (vy >>> 16)) >>> 0
  vx = (vx + Math.imul(vy, HM)) >>> 0
  vy = (vy + Math.imul(vx, HM)) >>> 0
  vx = (vx ^ (vx >>> 16)) >>> 0
  return vx / 4294967295
}
function vnoise(px: number, py: number) {
  const ix = Math.floor(px), iy = Math.floor(py), fx = px - ix, fy = py - iy
  const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy)
  const a = hash(ix, iy), b = hash(ix + 1, iy), c = hash(ix, iy + 1), d = hash(ix + 1, iy + 1)
  return (a + (b - a) * ux) * (1 - uy) + (c + (d - c) * ux) * uy
}
function fbm(px: number, py: number) {
  let s = 0, a = 0.5, t = 0
  for (let i = 0; i < 5; i++) {
    s += a * vnoise(px, py)
    t += a
    const nx = (0.8 * px - 0.6 * py) * 2.02 + 17.3
    const ny = (0.6 * px + 0.8 * py) * 2.02 + 17.3
    px = nx
    py = ny
    a *= 0.5
  }
  return s / t
}
function burnN(px: number, py: number, seed: number) {
  const qx = px / 210 + seed, qy = py / 210 + seed
  const wx = fbm(qx * 1.6 + 3.1, qy * 1.6 + 3.1), wy = fbm(qx * 1.6 + 7.7, qy * 1.6 + 7.7)
  return (fbm(qx + wx * 1.3, qy + wy * 1.3) - 0.5) * 2
}

/* ---- burns: each one turns the top page into the bottom page ---- */
type Part = { ts: number; x: number; y: number; vx: number; vy: number; buoy: number; sw: number; w: number; ph: number; sz: number; life: number; seed: number; spin?: number; grow?: number; bx?: number; by?: number }
type Burn = { cx: number; cy: number; t0: number; dur: number; seed: number; rmax: number; top: 'A' | 'B'; bot: 'A' | 'B'; E: Part[]; F: Part[]; S: Part[] }

const ampOf = (R: number) => 14 + Math.min(Math.max(R, 0) * 0.42, 200)
function radiusAt(b: Burn, t: number) {
  const k = Math.min(1, Math.max(0, (t - b.t0) / b.dur))
  const e = k * k * (1.6 - 0.6 * k)
  return -38 + (b.rmax + 330) * e
}
const inPage = (x: number, y: number, m: number) => x > m && x < PW - m && y > m && y < PH - m

function makeBurn(cx: number, cy: number, t0: number, dur: number, seed: number, tEnd: number, top: 'A' | 'B'): Burn {
  let rmax = 0
  for (const [x, y] of [[0, 0], [PW, 0], [0, PH], [PW, PH]]) rmax = Math.max(rmax, Math.hypot(x - cx, y - cy))
  const b: Burn = { cx, cy, t0, dur, seed, rmax, top, bot: top === 'A' ? 'B' : 'A', E: [], F: [], S: [] }
  let s = Math.floor(seed * 1e5) + 11
  const rnd = () => (s = (s * 16807) % 2147483647) / 2147483647
  const rimAt = (ts: number, th: number) => {
    const R = radiusAt(b, ts), amp = ampOf(R), dx = Math.cos(th), dy = Math.sin(th)
    let d = R
    for (let i = 0; i < 3; i++) d = R + burnN(cx + dx * d, cy + dy * d, seed) * amp * 1.6
    return [cx + dx * d, cy + dy * d]
  }
  const spawn = (n: number, list: Part[], ember: boolean, mk: (ts: number, x: number, y: number) => Part) => {
    for (let i = 0; i < n; i++) {
      const ts = t0 + 0.12 + (dur + 0.15) * Math.sqrt(rnd())
      const th = rnd() * 6.2832
      const p = rimAt(ts, th)
      if (!inPage(p[0], p[1], 3)) continue
      const o = mk(ts, p[0], p[1])
      o.life = Math.min(o.life, (ember ? tEnd : tEnd - 0.5) - ts)
      if (o.life > 0.2) list.push(o)
    }
  }
  spawn(Math.round(rmax * 1.5), b.E, true, (ts, x, y) => ({ ts, x, y, vx: (rnd() - 0.5) * 40, vy: 25 + rnd() * 70, buoy: 20 + rnd() * 50, sw: 10 + rnd() * 26, w: 2 + rnd() * 5, ph: rnd() * 6.3, sz: 9 + rnd() * 16, life: 0.7 + rnd() * rnd() * 2.6, seed: rnd() }))
  spawn(Math.round(rmax * 0.05), b.F, false, (ts, x, y) => ({ ts, x, y, vx: (rnd() - 0.5) * 30, vy: 20 + rnd() * 45, buoy: 12 + rnd() * 26, sw: 18 + rnd() * 30, w: 1.5 + rnd() * 3, ph: rnd() * 6.3, sz: 4 + rnd() * 7, life: 0.8 + rnd() * 1.3, spin: (rnd() - 0.5) * 9, seed: rnd() }))
