/* ---- shaders ---- */
const FSQ = `#version 300 es
in vec2 aP; void main(){ gl_Position = vec4(aP, 0., 1.); }`
const FFS = `#version 300 es
precision highp float;
uniform vec2 uView; uniform float uDpr; uniform vec2 uOrg; uniform vec2 uPage; uniform float uSc; uniform vec2 uUV;
uniform sampler2D uTop, uBot; uniform int uMode; uniform vec2 uC; uniform float uR, uAmp, uSeed, uTime, uFire, uFlash;
uniform vec3 uBg0, uBg1; uniform float uShadow, uLight;
