  return length(p-uC) - uR - burnN(p)*uAmp*1.6 + fine*(5. + uAmp*.06); }
float rbox(vec2 p, float r){ vec2 hs = uPage*.5; vec2 d = abs(p-hs) - hs + r; return length(max(d,0.)) + min(max(d.x,d.y),0.) - r; }
