  vec2 p = (fc - uOrg)/uSc;
  vec2 sv = fc/uView;
  float fl = .78 + .22*vnoise(vec2(uTime*11., 2.3)) * (.6 + .4*vnoise(vec2(uTime*4.1, 9.)));
  vec3 bg = mix(uBg0, uBg1, ss(.15, 1.05, length((sv-vec2(.5,.45))*vec2(1.25,1.))));
  bg += (vnoise(fc*.9) - .5) * .022 * uLight;
  float sr = mix(34., 50., uLight);
  float boxS = rbox(p - vec2(0., mix(18., 30., uLight)), 14.);
  bg *= 1. - uShadow*exp(-max(boxS,0.)/sr)*ss(-40.,0.,-boxS+20.);
  float box = rbox(p, 14.);
  bg *= 1. - .16*uLight*exp(-max(box,0.)*uSc/1.6);
  float glow = .14*uFire*fl*exp(-max(box,0.)/110.);
  bg = mix(bg + vec3(1.,.38,.08)*glow, mix(bg, vec3(1.,.5,.2), clamp(glow*1.5, 0., .5)), uLight);
  vec3 col = bg;
  float aa = 1./(uSc*uDpr);
  float pm = ss(aa, -aa, box);
  vec3 add = vec3(0.);
  if (box < 50.) {
    vec2 uvp = p/uPage*uUV;
    vec3 pc;
    if (uMode == 0) pc = texture(uTop, uvp).rgb;
    else if (uMode == 2) pc = texture(uBot, uvp).rgb;
    else {
      float f = burnF(p);
      float heat = exp(-abs(f)/55.) * uFire;
      vec2 rise = vec2(0., uTime*2.8);
      vec2 off = (vec2(vnoise(p/46. + rise), vnoise(p/46. + rise + 5.2)) - .5) * 5. * heat;
      vec3 top = texture(uTop, (p+off)/uPage*uUV).rgb;
      vec3 bot = texture(uBot, (p+off*.6)/uPage*uUV).rgb;
      float cw = 18. + 34.*fbm(p/64. + uSeed*3.);
      float toast = ss(cw*5.5, cw*.8, f);
      top = mix(top, top*vec3(.95,.76,.5), toast*.8);
      float sc = ss(cw*1.25, cw*.2, f);
      vec3 charC = mix(vec3(.30,.15,.06), vec3(.03,.022,.02), ss(cw*.8, cw*.25, f));
      charC *= .8 + .4*vnoise(p/3.);
      top = mix(top, charC, sc);
      vec2 g = vec2(dFdx(f), -dFdy(f)); g /= max(length(g), 1e-4);
      float lip = ss(14., 2., f) * ss(-1., 2., f);
      top += vec3(.35,.25,.18) * lip * max(0., dot(g, normalize(vec2(.6,.8)))) * .35;
      top += vec3(1.,.40,.09) * .55 * exp(-max(f,0.)/13.) * fl * uFire;
      float rim = exp(-max(f,0.)/2.4) * ss(-2.2, .6, f);
      float coal = ss(.60, .86, vnoise(p/4.2 + uSeed*9.)) * ss(cw*.9, 1., f) * (.45 + .55*vnoise(p/10. + vec2(uTime*3.3, -uTime*2.)));
      float e = (rim*(1.3 + .7*vnoise(p/16. + uTime*5.)) + coal*1.1) * fl * uFire;
      vec3 emC = mix(vec3(.7,.07,.01), vec3(1.,.46,.07), clamp(e,0.,1.));
      emC = mix(emC, vec3(1.,.9,.66), clamp(e-1.,0.,1.));
