      bot += vec3(1.,.38,.07) * .7 * exp(min(f,0.)/9.) * fl * uFire;
      float ash = ss(.55,.75, vnoise(p/2.6 + 3.)) * ss(-5., -1., f);
      bot = mix(bot, vec3(.42,.38,.35), ash*.5);
      pc = mix(bot, top, ss(-.8, .8, f));
