const PVS = `#version 300 es
in vec2 aQ; in vec4 aA; in vec4 aB;
uniform vec2 uView, uOrg; uniform float uSc;
out vec2 vQ; out vec4 vB; out float vAl;
void main(){ float c = cos(aB.y), s = sin(aB.y); vec2 q = mat2(c,s,-s,c)*aQ;
  vec2 sp = uOrg + (aA.xy + q*aA.z*.5)*uSc; gl_Position = vec4(sp.x/uView.x*2.-1., 1.-sp.y/uView.y*2., 0., 1.);
  vQ = aQ; vB = aB; vAl = aA.w; }`
const PFS = `#version 300 es
precision highp float; uniform int uKind; uniform float uTime, uLight; in vec2 vQ; in vec4 vB; in float vAl; out vec4 o;
${NOISE}
vec3 heatC(float h){ return h > .5 ? mix(vec3(1.,.42,.06), vec3(1.,.93,.7), (h-.5)*2.) : mix(vec3(.55,.05,.01), vec3(1.,.42,.06), h*2.); }
void main(){
  float r = length(vQ);
  if (uKind == 0) {
    float h = vB.x; float core = exp(-r*r*30.), halo = exp(-r*r*6.)*.5;
    vec3 c = (heatC(h*.85)*core*1.5 + vec3(1.,.32,.05)*halo*(.3+h)) * vAl;
    // light stage: deeper sparks blended over (premultiplied), so they read on pale paper as well as on the pages
    vec3 cl = c * vec3(1., .74, .5);
    float al = clamp(max(cl.r, max(cl.g, cl.b)), 0., 1.);
    o = mix(vec4(c, 1.), vec4(min(cl, vec3(al)), al*.9), uLight);
  } else if (uKind == 1) {
    float n = vnoise(vQ*2.2 + vB.z*40.);
    float a = ss(.95, .7, r + (n-.5)*.7);
    float h = vB.x;
    vec3 c = mix(vec3(.04,.03,.03), vec3(.13,.09,.07), n);
    float edge = ss(.45, .85, r + (n-.5)*.7) * a;
    c += heatC(h) * edge * h * 1.6;
    o = vec4(c, a * vAl);
  } else {
    float d = fbm(vQ*1.3 + vB.z*31. + vec2(0., -uTime*.25));
    float a = ss(1., .15, r) * ss(.35, .75, d);
    o = vec4(mix(vec3(.36,.32,.29), vec3(.30,.27,.25), uLight) * (.75 + .5*d), a * vAl * (1. + .35*uLight));
  }
}`

/* ---- the idle script (seconds into one 12 s loop; the clip's timeline) ---- */
const LOOP = 12
const IGN: [number, number] = [282, 452]
const ease = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2)
const lerp = (a: number, b: number, k: number) => a + (b - a) * k
const clamp01 = (x: number) => Math.min(1, Math.max(0, x))

type Rect = { x: number; y: number; w: number; h: number }
/** Element's box in its page's coordinates (layout px, immune to CSS scaling of the preview). */
function boxIn(el: HTMLElement, page: HTMLElement): Rect {
  let x = 0, y = 0
  let n: HTMLElement | null = el
  while (n && n !== page) {
    x += n.offsetLeft
    y += n.offsetTop
    n = n.offsetParent as HTMLElement | null
  }
  return { x, y, w: el.offsetWidth, h: el.offsetHeight }
}
const inRect = (x: number, y: number, r: Rect) => x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h

const ARTICLE_BODY =
  "There is a moment, just after you click, when a page is neither here nor there. Most of the web treats it as dead air: a flash of white, a spinner, a jolt. Print never had that problem. A page turned, and the next one was already waiting underneath, warm from the press. We built faster networks and forgot the part where leaving is part of the story. A good transition is not decoration. It is the hand that carries you from one thought to the next.";

