  const pbRef = React.useRef(null as HTMLDivElement | null);
  const curRef = React.useRef(null as SVGSVGElement | null);
  const ripRef = React.useRef(null as HTMLDivElement | null);
  const probeRef = React.useRef(null as HTMLSpanElement | null);
  const actRef = React.useRef(null as { press: () => void } | null);
  const props = React.useRef({ speed, intensity, autoplay, email, ctaLabel, ctaDoneLabel });
  React.useEffect(() => {
    props.current = { speed, intensity, autoplay, email, ctaLabel, ctaDoneLabel };
  });
  const [mode, setMode] = React.useState("gl" as "gl" | "fallback");
  const uid = React.useId().replace(/[^a-zA-Z0-9_-]/g, "");

  React.useEffect(() => {
    const root = rootRef.current, PA = paRef.current, PB = pbRef.current, cur = curRef.current, rip = ripRef.current, probe = probeRef.current
    if (!root || !PA || !PB || !cur || !rip || !probe) return
    const cv = mode === 'gl' ? canvasRef.current : null
    const fit = mode === 'fallback' ? fitRef.current : null
    let gl: WebGL2RenderingContext | null = null
    if (mode === 'gl') {
      gl = cv ? (cv.getContext('webgl2', { alpha: false, antialias: false, premultipliedAlpha: false }) as WebGL2RenderingContext | null) : null
      if (!gl || !(gl as unknown as { texElementSubImage2D?: unknown }).texElementSubImage2D) {
        let live = true
        queueMicrotask(() => { if (live) setMode('fallback') })
        return () => { live = false }
      }
    }

    /* ---- stage colours from the theme (CSS variables → uniforms), re-read when the theme changes ---- */
    let bg0 = [0.085, 0.06, 0.05], bg1 = [0.012, 0.01, 0.01], shadow = 0.72, light = 0, sig = ''
    const pc = document.createElement('canvas')
    pc.width = pc.height = 1
    const px = pc.getContext('2d', { willReadFrequently: true })
    const rgbOf = (k: string, d: number[]) => {
      probe.style.color = `var(--ba-${k})`
      const c = getComputedStyle(probe).color
      if (!px || !c) return d
      px.clearRect(0, 0, 1, 1)
      px.fillStyle = '#000'
      px.fillStyle = c
      px.fillRect(0, 0, 1, 1)
      const v = px.getImageData(0, 0, 1, 1).data
      return [v[0] / 255, v[1] / 255, v[2] / 255]
    }
    const readStage = () => {
      const cs = getComputedStyle(root)
      const s = ['bg0', 'bg1', 'sh', 'light'].map((k) => cs.getPropertyValue('--ba-' + k)).join('|')
      if (s === sig) return false
      sig = s
      bg0 = rgbOf('bg0', bg0)
      bg1 = rgbOf('bg1', bg1)
      const sh = parseFloat(cs.getPropertyValue('--ba-sh'))
      shadow = Number.isFinite(sh) ? sh : 0.72
      light = parseFloat(cs.getPropertyValue('--ba-light')) > 0.5 ? 1 : 0
      return true
    }
    let frames = 0
    const em = PB.querySelector('input') as HTMLInputElement
    const go = PB.querySelector('button') as HTMLButtonElement
    const barEls = Array.from(PB.querySelectorAll('.ba-bars i')) as HTMLElement[]
    const ctr = PB.querySelector('.ba-ctr') as HTMLElement
    const fpsEl = PB.querySelector('.ba-fps') as HTMLElement
    const msEl = PB.querySelector('.ba-ms') as HTMLElement
    const sitesEl = PB.querySelector('.ba-sites') as HTMLElement
    const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches
    const DPR = Math.min(devicePixelRatio || 1, 2)

    let W = 0, H = 0, SC = 1, OX = 0, OY = 0, BK = 1
    let uvx = 1, uvy = 1, kx = 1, ky = 1
    let T = 0 // scene clock, seconds (scaled by speed)
    let wall = 0 // unscaled clock for the live counters
    let raf = 0, visible = true, last = performance.now()
    let showing: 'A' | 'B' = 'A'
    let burns: Burn[] = []
    let ap = false // idle script running
    let apStart = 0
    let lastInput = -1e9
    let focusAt = -1
    let goR: Rect = { x: 0, y: 0, w: 0, h: 0 }
    let emR: Rect = { x: 0, y: 0, w: 0, h: 0 }

    const measure = () => {
      goR = boxIn(go, PB)
      emR = boxIn(em, PB)
    }
    const resize = () => {
      W = root.offsetWidth
      H = root.offsetHeight
      const m = Math.max(8, Math.min(40, Math.min(W, H) * 0.045))
      const res = badge || mode === 'fallback' ? (W < 620 ? 40 : 48) : 0
      SC = Math.max(0.05, Math.min(1.25, (W - 2 * m) / PW, (H - 2 * m - res) / PH))
      OX = (W - PW * SC) / 2
      OY = Math.max(m, (H - res - PH * SC) / 2)
