      cur.style.width = cur.style.height = Math.round(30 * Math.max(0.6, Math.min(1, SC * 1.4))) + 'px'
    }

    /* ---- page B is alive: counters, bars ---- */
    const liveB = (t: number) => {
      ctr.textContent = Math.floor(1284093 + t * 1873 + Math.sin(t * 3) * 40).toLocaleString('en-US')
      sitesEl.textContent = Math.floor(8412 + t * 1.6).toLocaleString('en-US')
      fpsEl.textContent = String(118 + Math.round(2 * Math.sin(t * 5.3)))
      msEl.textContent = (0.42 + 0.03 * Math.sin(t * 7.1)).toFixed(2)
      for (let i = 0; i < barEls.length; i++) {
