    }

    /* ---- live: click to burn ---- */
    const ignite = (x: number, y: number) => {
      prune()
      const from = showing
      if (from === 'A') resetB()
      if (reduced) {
        showing = from === 'A' ? 'B' : 'A'
        burns = []
        if (showing === 'B') em.focus({ preventScroll: true })
        frame()
        return
      }
      const b = makeBurn(x, y, T, 3.2 + Math.random() * 0.8, Math.random() * 9, 1e9, from)
      burns.push(b)
      focusAt = from === 'A' ? T + b.dur * 0.75 : -1
      if (from === 'B' && document.activeElement === em) em.blur()
    }
    const press = () => {
      if (busy() || front() !== 'B') return
      takeOver()
      setOk(true)
      go.classList.add('ba-down')
      setTimeout(() => go.classList.remove('ba-down'), 160)
      ignite(goR.x + goR.w / 2 - 30, goR.y + goR.h / 2)
    }
    actRef.current = { press }
    const takeOver = () => {
      lastInput = performance.now()
      stopAuto()
      start()
    }
    const toPage = (e: PointerEvent): [number, number] => {
      const r = root.getBoundingClientRect()
      const kx = r.width ? root.offsetWidth / r.width : 1, ky = r.height ? root.offsetHeight / r.height : 1
      return [((e.clientX - r.left) * kx - OX) / SC, ((e.clientY - r.top) * ky - OY) / SC]
    }
    const onDown = (e: PointerEvent) => {
      if (e.button !== 0) return
      takeOver()
      const p = toPage(e)
      if (!inPage(p[0], p[1], 0) || busy()) return
      measure()
      if (front() === 'B') {
        if (inRect(p[0], p[1], emR)) {
          e.preventDefault()
          em.focus({ preventScroll: true })
          return
        }
        if (inRect(p[0], p[1], goR)) {
          e.preventDefault()
          press()
          return
        }
      }
      e.preventDefault()
      ignite(p[0], p[1])
    }
    const onMove = (e: PointerEvent) => {
      if (ap) return
      const p = toPage(e)
      const on = inPage(p[0], p[1], 0)
      const b = front() === 'B' && !busy()
      const overBtn = b && inRect(p[0], p[1], goR)
      const overEm = b && inRect(p[0], p[1], emR)
      go.classList.toggle('ba-hov', overBtn)
      root.style.cursor = overEm ? 'text' : on && !busy() ? 'pointer' : ''
      lastInput = performance.now()
    }
    const onLeave = () => go.classList.remove('ba-hov')
    const onKey = (e: KeyboardEvent) => {
      if (e.target === em && e.key === 'Enter') {
        e.preventDefault()
        press()
        return
      }
      takeOver()
    }
    const onFocusIn = () => takeOver()

    /* ---- WebGL ---- */
    type Tex = { t: WebGLTexture; w: number; h: number }
    let TA: Tex | null = null, TB: Tex | null = null, hasTex = false
    let PF: WebGLProgram | null = null, PP: WebGLProgram | null = null
    const shaders: WebGLShader[] = []
    const buffers: WebGLBuffer[] = []
    const vaos: WebGLVertexArrayObject[] = []
    let fva: WebGLVertexArrayObject | null = null, pva: WebGLVertexArrayObject | null = null, ib: WebGLBuffer | null = null
    const MAXP = 6000
    const pdata = new Float32Array(MAXP * 8)
    const ul = new Map() as Map<string, WebGLUniformLocation | null>
    const u = (p: WebGLProgram, tag: string, n: string) => {
      const key = tag + n
      if (!ul.has(key)) ul.set(key, gl!.getUniformLocation(p, n))
      return ul.get(key)!
    }
    const upload = (T: Tex, el: HTMLElement) => {
      const g = gl as WebGL2RenderingContext & { texElementSubImage2D: (...a: unknown[]) => void }
      // the element is drawn at the canvas's backing ratio (canvas px / CSS px), which can be fractional
      const w = Math.ceil(el.offsetWidth * kx) + 2, h = Math.ceil(el.offsetHeight * ky) + 2
      uvx = (el.offsetWidth * kx) / w
      uvy = (el.offsetHeight * ky) / h
      g.bindTexture(g.TEXTURE_2D, T.t)
      if (w !== T.w || h !== T.h) {
        g.texImage2D(g.TEXTURE_2D, 0, g.RGBA8, w, h, 0, g.RGBA, g.UNSIGNED_BYTE, null)
        T.w = w
        T.h = h
        g.texParameteri(g.TEXTURE_2D, g.TEXTURE_MIN_FILTER, g.LINEAR)
        g.texParameteri(g.TEXTURE_2D, g.TEXTURE_MAG_FILTER, g.LINEAR)
        g.texParameteri(g.TEXTURE_2D, g.TEXTURE_WRAP_S, g.CLAMP_TO_EDGE)
        g.texParameteri(g.TEXTURE_2D, g.TEXTURE_WRAP_T, g.CLAMP_TO_EDGE)
      }
      g.texElementSubImage2D(g.TEXTURE_2D, 0, 0, 0, el)
    }
    if (gl && cv) {
      const g = gl
      const prog = (vs: string, fs: string) => {
        const p = g.createProgram()!
        for (const [type, src] of [[g.VERTEX_SHADER, vs], [g.FRAGMENT_SHADER, fs]] as [number, string][]) {
          const sh = g.createShader(type)!
          g.shaderSource(sh, src)
          g.compileShader(sh)
          if (!g.getShaderParameter(sh, g.COMPILE_STATUS)) console.error('BurnAway shader', g.getShaderInfoLog(sh))
          g.attachShader(p, sh)
          shaders.push(sh)
        }
        g.linkProgram(p)
        return p
      }
      PF = prog(FSQ, FFS)
      PP = prog(PVS, PFS)
      fva = g.createVertexArray()!
      vaos.push(fva)
      g.bindVertexArray(fva)
      const fb = g.createBuffer()!
      buffers.push(fb)
      g.bindBuffer(g.ARRAY_BUFFER, fb)
      g.bufferData(g.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), g.STATIC_DRAW)
      let l = g.getAttribLocation(PF, 'aP')
      g.enableVertexAttribArray(l)
      g.vertexAttribPointer(l, 2, g.FLOAT, false, 0, 0)
      pva = g.createVertexArray()!
      vaos.push(pva)
      g.bindVertexArray(pva)
      const qb = g.createBuffer()!
      buffers.push(qb)
      g.bindBuffer(g.ARRAY_BUFFER, qb)
      g.bufferData(g.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), g.STATIC_DRAW)
      l = g.getAttribLocation(PP, 'aQ')
      g.enableVertexAttribArray(l)
      g.vertexAttribPointer(l, 2, g.FLOAT, false, 0, 0)
      ib = g.createBuffer()!
      buffers.push(ib)
      g.bindBuffer(g.ARRAY_BUFFER, ib)
      g.bufferData(g.ARRAY_BUFFER, pdata.byteLength, g.DYNAMIC_DRAW)
      l = g.getAttribLocation(PP, 'aA')
      g.enableVertexAttribArray(l)
      g.vertexAttribPointer(l, 4, g.FLOAT, false, 32, 0)
      g.vertexAttribDivisor(l, 1)
      l = g.getAttribLocation(PP, 'aB')
      g.enableVertexAttribArray(l)
      g.vertexAttribPointer(l, 4, g.FLOAT, false, 32, 16)
      g.vertexAttribDivisor(l, 1)
      g.bindVertexArray(null)
      TA = { t: g.createTexture()!, w: 0, h: 0 }
      TB = { t: g.createTexture()!, w: 0, h: 0 }
      ;(cv as HTMLCanvasElement & { onpaint: (() => void) | null }).onpaint = () => {
        try {
          upload(TA!, PA)
          upload(TB!, PB)
          hasTex = true
          if (!raf) render(T)
        } catch (err) {
          console.error('BurnAway upload', err)
        }
      }
    }
    const requestPaint = () => (cv as (HTMLCanvasElement & { requestPaint?: () => void }) | null)?.requestPaint?.()

    const fillKind = (t: number, kind: number) => {
      let n = 0
      const amp = Math.min(1.5, props.current.intensity)
      for (const b of burns) {
        if (t < b.t0 || t > b.t0 + b.dur + 6) continue
        const L = kind === 0 ? b.E : kind === 1 ? b.F : b.S
        for (const o of L) {
          const a = t - o.ts
          if (a < 0 || a > o.life || n >= MAXP) continue
          const k = a / o.life
          let x = o.x + o.vx * a + Math.sin(a * o.w + o.ph) * o.sw * Math.min(1, a)
          let y = o.y - (o.vy * a + 0.5 * o.buoy * a * a)
          if (o.bx !== undefined) {
            const kk = (1 - Math.exp(-3.2 * a)) / 3.2
            x += o.bx * kk
            y += (o.by ?? 0) * kk
          }
          const i = n * 8
          pdata[i] = x
          pdata[i + 1] = y
          pdata[i + 6] = o.seed
          pdata[i + 7] = 0
          if (kind === 0) {
            const h = Math.pow(1 - k, 0.8) * (o.bx !== undefined ? 1 : 0.85 + 0.15 * o.seed)
            const fl = 0.7 + 0.3 * Math.sin(t * 31 + o.seed * 60)
            pdata[i + 2] = o.sz * (0.55 + 0.45 * h)
            pdata[i + 3] = Math.min(1, a / 0.06) * fl * Math.min(1, (1 - k) * 4) * amp
            pdata[i + 4] = h
            pdata[i + 5] = 0
          } else if (kind === 1) {
            pdata[i + 2] = o.sz
            pdata[i + 3] = Math.min(1, a / 0.1) * Math.min(1, (1 - k) * 3)
            pdata[i + 4] = Math.max(0, 1 - k * 2.2) * Math.min(1, amp)
            pdata[i + 5] = o.ph + (o.spin ?? 0) * a
          } else {
            pdata[i + 2] = o.sz + (o.grow ?? 0) * a
            pdata[i + 3] = 0.2 * Math.sin(Math.PI * k) * (1 - k * 0.5)
            pdata[i + 4] = 0
            pdata[i + 5] = o.ph
          }
          n++
        }
      }
      return n
    }
    const drawKind = (t: number, kind: number) => {
      const g = gl!
      const n = fillKind(t, kind)
      if (!n) return
      g.bindBuffer(g.ARRAY_BUFFER, ib)
      g.bufferSubData(g.ARRAY_BUFFER, 0, pdata, 0, n * 8)
      if (kind === 0) g.blendFuncSeparate(g.ONE, light ? g.ONE_MINUS_SRC_ALPHA : g.ONE, g.ZERO, g.ONE)
      else g.blendFuncSeparate(g.SRC_ALPHA, g.ONE_MINUS_SRC_ALPHA, g.ZERO, g.ONE)
      g.uniform1i(u(PP!, 'p', 'uKind'), kind)
      g.drawArraysInstanced(g.TRIANGLE_STRIP, 0, 4, n)
    }
    const latest = (t: number) => {
      let b: Burn | null = null
      for (const x of burns) if (t >= x.t0) b = x
      return b
    }
    const render = (t: number) => {
      if (!gl) {
        // fallback: the same pages, crossfaded where the burn would open
        const b = latest(t)
        const vis = b ? ((t - b.t0) / b.dur > 0.35 ? b.bot : b.top) : showing
        PA.style.opacity = vis === 'A' ? '1' : '0'
        return
      }
      const g = gl
      g.disable(g.BLEND)
      g.clearColor(bg1[0], bg1[1], bg1[2], 1)
      g.clear(g.COLOR_BUFFER_BIT)
      if (!hasTex || W < 2 || H < 2 || !TA || !TB) return
      const b = latest(t)
      let md = 0, R = -1e4, amp = 0, fire = 0, flash = 0
      let top = showing === 'A' ? TA : TB, bot = showing === 'A' ? TB : TA
      if (b) {
        top = b.top === 'A' ? TA : TB
        bot = b.top === 'A' ? TB : TA
        md = t > b.t0 + b.dur + 0.35 ? 2 : 1
        R = radiusAt(b, t)
        amp = ampOf(R)
        const k = (t - b.t0) / b.dur
        fire = Math.min(1, k * 6 + 0.25) * (k > 1 ? Math.max(0, 1 - (k - 1) / 0.08) : 1)
        flash = Math.max(0, 1 - (t - b.t0) / 0.45)
        flash *= flash
      }
      const I = props.current.intensity
      g.useProgram(PF)
      g.bindVertexArray(fva)
      g.uniform2f(u(PF!, 'f', 'uView'), W, H)
      g.uniform1f(u(PF!, 'f', 'uDpr'), cv!.width / Math.max(1, W))
      g.uniform2f(u(PF!, 'f', 'uUV'), uvx, uvy)
      g.uniform2f(u(PF!, 'f', 'uOrg'), OX, OY)
      g.uniform2f(u(PF!, 'f', 'uPage'), PW, PH)
      g.uniform1f(u(PF!, 'f', 'uSc'), SC)
      g.activeTexture(g.TEXTURE0)
      g.bindTexture(g.TEXTURE_2D, top.t)
      g.uniform1i(u(PF!, 'f', 'uTop'), 0)
      g.activeTexture(g.TEXTURE1)
      g.bindTexture(g.TEXTURE_2D, bot.t)
      g.uniform1i(u(PF!, 'f', 'uBot'), 1)
      g.uniform1i(u(PF!, 'f', 'uMode'), md)
      g.uniform2f(u(PF!, 'f', 'uC'), b ? b.cx : 0, b ? b.cy : 0)
      g.uniform1f(u(PF!, 'f', 'uR'), R)
      g.uniform1f(u(PF!, 'f', 'uAmp'), amp)
      g.uniform1f(u(PF!, 'f', 'uSeed'), b ? b.seed : 0)
      g.uniform1f(u(PF!, 'f', 'uTime'), t)
      g.uniform1f(u(PF!, 'f', 'uFire'), fire * I)
      g.uniform1f(u(PF!, 'f', 'uFlash'), flash * Math.min(1.3, I))
      g.uniform3f(u(PF!, 'f', 'uBg0'), bg0[0], bg0[1], bg0[2])
      g.uniform3f(u(PF!, 'f', 'uBg1'), bg1[0], bg1[1], bg1[2])
      g.uniform1f(u(PF!, 'f', 'uShadow'), shadow)
      g.uniform1f(u(PF!, 'f', 'uLight'), light)
      g.drawArrays(g.TRIANGLES, 0, 3)
      g.enable(g.BLEND)
      g.useProgram(PP)
      g.bindVertexArray(pva)
      g.uniform2f(u(PP!, 'p', 'uView'), W, H)
      g.uniform2f(u(PP!, 'p', 'uOrg'), OX, OY)
      g.uniform1f(u(PP!, 'p', 'uSc'), SC)
      g.uniform1f(u(PP!, 'p', 'uTime'), t)
      g.uniform1f(u(PP!, 'p', 'uLight'), light)
      drawKind(t, 2)
      drawKind(t, 1)
      drawKind(t, 0)
      g.bindVertexArray(null)
    }
    const frame = () => {
      requestPaint()
      render(T)
    }

    const loop = (now: number) => {
      raf = 0
      const dt = Math.max(0, Math.min(0.05, (now - last) / 1000))
      last = now
      wall += dt
      T += dt * props.current.speed
      const P = props.current
      if (ap) {
        if (!P.autoplay) stopAuto()
        else {
          if (T - apStart >= LOOP) startAuto(0)
          script(T - apStart)
        }
      } else if (P.autoplay && performance.now() - lastInput > 6000 && !busy() && !root.contains(document.activeElement)) {
        startAuto(front() === 'A' ? 0 : 4.9)
      }
      if (focusAt > 0 && T >= focusAt) {
        focusAt = -1
        if (!ap && front() === 'B') em.focus({ preventScroll: true })
      }
      liveB(wall)
      if (gl && ++frames % 20 === 0) readStage()
      frame()
      if (visible && !document.hidden) raf = requestAnimationFrame(loop)
    }
    function start() {
      if (reduced || raf || !visible || document.hidden) return
      last = performance.now()
      raf = requestAnimationFrame(loop)
    }

    const ro = new ResizeObserver(() => {
      resize()
      measure()
      frame()
    })
    const io = new IntersectionObserver(([en]) => {
      visible = en.isIntersecting
      if (visible) start()
    })
    const onVis = () => {
      if (!document.hidden) start()
    }
    // theme switches (a .dark class or data-theme on <html>/<body>, or the theme prop) repaint even when paused
    const mo = new MutationObserver(() => {
      if (gl && readStage() && !raf) frame()
    })
    for (const el of [document.documentElement, document.body, root]) if (el) mo.observe(el, { attributes: true, attributeFilter: ['class', 'data-theme', 'data-ba-theme', 'style'] })
    if (gl) readStage()

    resize()
    measure()
    liveB(0)
    if (reduced) {
      // still frame: the article half burned open onto the landing page
      T = 2.4
      burns = [makeBurn(IGN[0], IGN[1], 0, 4.5, 0.37, 1e9, 'A')]
      frame()
    } else if (props.current.autoplay) startAuto(0)
    ro.observe(root)
    io.observe(root)
    root.addEventListener('pointerdown', onDown)
    root.addEventListener('pointermove', onMove)
    root.addEventListener('pointerleave', onLeave)
    root.addEventListener('keydown', onKey)
    root.addEventListener('focusin', onFocusIn)
    document.addEventListener('visibilitychange', onVis)
    frame()
    start()

    return () => {
      cancelAnimationFrame(raf)
      raf = 0
      ro.disconnect()
      io.disconnect()
      mo.disconnect()
      root.removeEventListener('pointerdown', onDown)
      root.removeEventListener('pointermove', onMove)
      root.removeEventListener('pointerleave', onLeave)
      root.removeEventListener('keydown', onKey)
      root.removeEventListener('focusin', onFocusIn)
      document.removeEventListener('visibilitychange', onVis)
      actRef.current = null
      if (cv) (cv as HTMLCanvasElement & { onpaint: (() => void) | null }).onpaint = null
      if (gl) {
        const g = gl
        for (const v of vaos) g.deleteVertexArray(v)
        for (const b of buffers) g.deleteBuffer(b)
        if (PF) g.deleteProgram(PF)
        if (PP) g.deleteProgram(PP)
        for (const s of shaders) g.deleteShader(s)
        if (TA) g.deleteTexture(TA.t)
        if (TB) g.deleteTexture(TB.t)
      }
    }
  }, [mode, badge])

  const sky = `ba-sky-${uid}`, dots = `ba-dots-${uid}`, dots2 = `ba-dots2-${uid}`
  const drawable = mode === 'gl' ? ({ drawable: '' } as Record<string, string>) : {}

  const pageB = (
    <div ref={pbRef} className="ba-page ba-pb" {...drawable}>
      <header><span className="ba-logo"><i></i>{productName}</span><nav><span>Product</span><span>Pricing</span><span>Changelog</span><span>Docs</span></nav><span className="ba-sign">Sign in</span></header>
      <main>
        <section className="ba-hero">
          <div className="ba-pill"><b>New</b>Page transitions, rendered on the GPU</div>
          <h1>{headline} <span>{headlineAccent}</span></h1>
          <p className="ba-sub">{tagline ?? <>{productName} turns the space between two pages into a moment people remember. One tag. No rebuild.</>}</p>
          <form onSubmit={(e) => { e.preventDefault(); actRef.current?.press() }}>
            <input type="email" placeholder={emailPlaceholder} autoComplete="off" spellCheck={false} aria-label="Email" tabIndex={-1} />
            <button type="button" tabIndex={-1} onClick={() => actRef.current?.press()}>{ctaLabel}</button>
          </form>
          <div className="ba-note">{finePrint}</div>
        </section>
        <aside className="ba-dash">
          <div className="ba-row"><span>Transitions served today</span><span className="ba-live"><i></i>LIVE</span></div>
          <div className="ba-big ba-ctr">1,284,093</div>
          <div className="ba-delta">▲ 18.4% vs yesterday</div>
          <div className="ba-bars">{Array.from({ length: NBARS }, (_, i) => <i key={i}></i>)}</div>
          <div className="ba-stats"><div><b className="ba-fps">120</b>frames / sec</div><div><b className="ba-ms">0.42</b>ms per frame</div><div><b className="ba-sites">8,412</b>sites live</div></div>
        </aside>
      </main>
      <footer><span>Trusted by 12,000 studios</span><span>Kestrel</span><span>HALDEN&amp;CO</span><span>Orbitals</span><span>PAPERMILL</span><span>juniper/</span></footer>
    </div>
  )
  const pageA = (
    <div ref={paRef} className="ba-page ba-pa" {...drawable}>
      <header className="ba-mast"><span className="ba-logo">The <i>{magazine}</i></span><nav><span>Essays</span><span>Craft</span><span>Interviews</span><span>Archive</span></nav><span className="ba-iss">No. 41 · Winter</span></header>
      <main>
        <section className="ba-lede">
          <div className="ba-kick">{kicker}</div>
          <h1>{articleTitle}</h1>
          <p className="ba-stand">{articleStandfirst}</p>
          <div className="ba-by">{byline}</div>
          <div className="ba-body"><p><span className="ba-dc">{articleBody.charAt(0)}</span>{articleBody.slice(1)}</p></div>
        </section>
        <aside>
          <figure><svg viewBox="0 0 368 262" width="368" height="262" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
            <defs>
              <linearGradient id={sky} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#f6c453" /><stop offset=".62" stopColor="#f29a4a" /><stop offset="1" stopColor="#e8704a" /></linearGradient>
              <pattern id={dots} width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r="1.25" fill="#b8301e" /></pattern>
              <pattern id={dots2} width="5" height="5" patternUnits="userSpaceOnUse"><circle cx="2.5" cy="2.5" r="1" fill="#0f1f45" opacity=".55" /></pattern>
            </defs>
            <rect width="368" height="262" fill={`url(#${sky})`} />
            <circle cx="232" cy="128" r="70" fill="#e4492f" /><circle cx="232" cy="128" r="70" fill={`url(#${dots})`} opacity=".55" />
            <g fill="none" stroke="#fff6e4" strokeWidth="2" strokeLinecap="round" opacity=".8"><path d="M30 60 q10 -8 20 0 q10 8 20 0" /><path d="M300 44 q8 -6 16 0 q8 6 16 0" /></g>
            <path d="M0 176 C60 140 110 150 160 170 C210 190 260 150 368 160 V262 H0Z" fill="#2c4d8f" />
            <path d="M0 176 C60 140 110 150 160 170 C210 190 260 150 368 160 V262 H0Z" fill={`url(#${dots2})`} />
            <path d="M0 208 C70 186 130 196 196 214 C260 232 310 200 368 204 V262 H0Z" fill="#1b2f5e" />
            <path d="M0 238 C80 222 150 228 220 244 C290 258 330 236 368 238 V262 H0Z" fill="#0f1f45" />
            <g transform="translate(108 112) rotate(-14)"><path d="M0 14 L44 0 L18 22 Z" fill="#fff6e4" /><path d="M18 22 L44 0 L22 30 Z" fill="#e8dcc4" /></g>
            <path d="M100 132 q-30 18 -64 6" fill="none" stroke="#fff6e4" strokeWidth="1.6" strokeDasharray="3 5" opacity=".9" />
          </svg></figure>
          <figcaption>Fig. 1 — The page that is already waiting. Illustration: Teo Brandt for The {magazine}.</figcaption>
          <blockquote>{pullQuote}<small>— From the essay</small></blockquote>
        </aside>
      </main>
    </div>
  )

  return (
    <div ref={rootRef} className={'ba-root' + (className ? ' ' + className : '')} style={style} data-ba-theme={theme === 'auto' ? undefined : theme} role="region" aria-label="Two web pages; click one to burn it away into the other">
      <style>{CSS}</style>
      <span ref={probeRef} className="ba-probe" aria-hidden="true" />
      {mode === 'gl' ? (
        <canvas key="gl" ref={canvasRef} className="ba-cv" {...({ layoutsubtree: '', content: 'drawable' } as Record<string, string>)}>
          {pageB}
          {pageA}
        </canvas>
      ) : (
        <div key="fb" ref={fitRef} className="ba-fit">
          {pageB}
          {pageA}
        </div>
      )}
      <svg ref={curRef} className="ba-cur" viewBox="0 0 30 30" aria-hidden="true"><path d="M5 3 L5 24 L10.5 19 L14.2 27 L18 25.3 L14.4 17.6 L21.5 17.2 Z" fill="#fff" stroke="#120d0a" strokeWidth="1.8" strokeLinejoin="round" /></svg>
      <div ref={ripRef} className="ba-rip" aria-hidden="true" />
      {mode === 'fallback' ? (
        <div className="ba-tag"><i></i><b>Open in Chrome 157+</b><span className="ba-keep">to see the WebGL effect</span></div>
      ) : badge ? (
        <div className="ba-tag"><i></i><b>Two real HTML pages</b><span className="ba-long">· one burned into the other with WebGL and HTML-in-Canvas</span><span>· click to light it</span></div>
      ) : null}
    </div>
  )
}

export { BurnAway };

